// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 count) public {
        vm.assume(count > 0 && count <= 100);
        address sender = address(0x1234);
        vm.deal(sender, count * 1 ether);
        vm.startPrank(sender);
        for (uint256 i = 0; i < count; i++) {
            (bool ok,) = address(c).call{value: 1 ether}("");
            require(ok, "deposit failed");
        }
        vm.stopPrank();
        uint256 balance = address(c).balance;
        uint256 dc = c.depositsCount();
        assertTrue(dc >= balance / 1 ether);
    }
}
